SELECT rating_bucket, uk_rating FROM (SELECT CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN country = 'UK' THEN rating ELSE 0 END) AS uk_rating FROM suppliers GROUP BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END) AS agg WHERE uk_rating >= 68 ORDER BY uk_rating DESC, rating_bucket LIMIT 1
